<span class="line">        <span class="token keyword">this</span><span class="token punctuation">.</span>$message<span class="token punctuation">.</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token string">&quot;转码请求失败！&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
